def test_extract_model_name_empty():
    assert extract_model_name(None) == ""
    assert extract_model_name({}) == ""


def test_extract_model_name_single_key():
    assert extract_model_name({"claude-sonnet-4-6": {"outputTokens": 100}}) == (
        "claude-sonnet-4-6"
    )


def test_extract_model_name_multi_picks_highest_output():
    model_usage = {
        "claude-haiku-4-5": {"outputTokens": 10},
        "claude-opus-4-7": {"outputTokens": 500},
        "claude-sonnet-4-6": {"outputTokens": 100},
    }
    assert extract_model_name(model_usage) == "claude-opus-4-7"


def test_extract_model_name_multi_nondict_values():
    """Non-dict values tolerated -- lexicographic tiebreaker picks the
    earlier key so the result is deterministic across dict orderings."""
    assert extract_model_name({"a": None, "b": None}) == "a"
    # Order-independent: reversing the input still picks 'a'.
    assert extract_model_name({"b": None, "a": None}) == "a"


